/**
 * Goal brake, trip live (#4684 option A).
 *
 * Fixtures are shaped like the live CC 2.1.332 /goal run: one UserPromptSubmit,
 * then one Stop per turn with stop_hook_active false on turn 1 and true on every
 * continuation, and the same prompt_id on all of them and on every tool call.
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { appendFileSync, existsSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

import { goalBudgetGuard } from '../../lifecycle/goal-budget-guard.js';
import { goalTracker } from '../../prompt/goal-tracker.js';
import { goalTrackerStop } from '../../stop/goal-tracker.js';
import { toolDispatcher } from '../../pretool/tool-dispatcher.js';
import { brakePath, findOpenRun } from '../../lib/goal-run.js';
import type { HookInput } from '../../types.js';
import { createTestContext } from '../fixtures/test-context.js';

const SID = 'sess-brake';
const RUN = 'prompt-run-1';
const CONDITION = 'count.txt holds the number 3';
const SILENT = { continue: true, suppressOutput: true };
const ENV = ['ORK_GOAL_MAX_TURNS', 'ORK_GOAL_MAX_TOKENS', 'ORK_GOAL_MAX_TURNS_PER_SESSION', 'ORK_GOAL_MAX_TOKENS_PER_SESSION'];

let tmp: string;
let prevPluginData: string | undefined;

beforeEach(() => {
  tmp = mkdtempSync(join(tmpdir(), 'goal-brake-'));
  prevPluginData = process.env.CLAUDE_PLUGIN_DATA;
  process.env.CLAUDE_PLUGIN_DATA = join(tmp, 'plugin-data');
  for (const name of ENV) delete process.env[name];
});

afterEach(() => {
  // The dispatcher's webhook forward can still be writing under tmp: retry.
  rmSync(tmp, { recursive: true, force: true, maxRetries: 10, retryDelay: 50 });
  if (prevPluginData === undefined) delete process.env.CLAUDE_PLUGIN_DATA;
  else process.env.CLAUDE_PLUGIN_DATA = prevPluginData;
  for (const name of ENV) delete process.env[name];
});

const ctx = (sessionId = SID) => createTestContext({ projectDir: tmp, sessionId });

function submit(prompt: string, promptId = RUN, sessionId = SID) {
  return goalTracker(
    { hook_event: 'UserPromptSubmit', tool_name: '', session_id: sessionId, tool_input: {}, prompt, prompt_id: promptId },
    ctx(sessionId),
  );
}

function stop(turn: number, promptId = RUN, sessionId = SID) {
  const input: HookInput = {
    hook_event: 'Stop',
    tool_name: '',
    session_id: sessionId,
    tool_input: {},
    prompt_id: promptId,
    stop_hook_active: turn > 1,
    last_assistant_message: `turn ${turn}: the goal is not met yet.`,
  };
  return goalTrackerStop(input, ctx(sessionId));
}

function toolCall(over: Partial<HookInput> = {}) {
  return toolDispatcher(
    {
      hook_event: 'PreToolUse',
      tool_name: 'Grep',
      session_id: SID,
      prompt_id: RUN,
      tool_input: { pattern: 'x' },
      ...over,
    },
    ctx(),
    {},
  );
}

function history(): Array<Record<string, unknown>> {
  const raw = readFileSync(join(tmp, '.claude', 'state', 'goal-history.jsonl'), 'utf8');
  return raw.trim().split('\n').map(line => JSON.parse(line) as Record<string, unknown>);
}

const openRun = (sessionId = SID) =>
  findOpenRun(readFileSync(join(tmp, '.claude', 'state', 'goal-history.jsonl'), 'utf8'), sessionId);

describe('Stop tallies the whole run, not the first turn', () => {
  it('counts 3 turns for 3 Stops shaped like the live run, and keeps the run open', () => {
    submit(`/goal ${CONDITION}`);
    for (const turn of [1, 2, 3]) stop(turn);

    expect(openRun()?.tally?.turn_count).toBe(3);
    expect(history().some(entry => entry.ended_at)).toBe(false);
  });

  it('never produces output, tripped or not', () => {
    process.env.ORK_GOAL_MAX_TURNS = '2';
    submit(`/goal ${CONDITION}`);
    for (const turn of [1, 2, 3]) expect(stop(turn)).toEqual(SILENT);
  });

  it('ignores a Stop that belongs to another prompt', () => {
    submit(`/goal ${CONDITION}`);
    stop(1);
    stop(2, 'prompt-other');
    expect(openRun()?.tally?.turn_count).toBe(1);
  });

  it('accumulates tokens across turns', () => {
    submit(`/goal ${CONDITION}`);
    stop(1);
    const first = openRun()?.tally?.ended_token_estimate ?? 0;
    stop(2);
    expect(openRun()?.tally?.ended_token_estimate ?? 0).toBeGreaterThan(first);
  });
});

describe('the brake file', () => {
  it('is not written under the cap', () => {
    process.env.ORK_GOAL_MAX_TURNS = '3';
    submit(`/goal ${CONDITION}`);
    stop(1);
    stop(2);
    expect(existsSync(brakePath(tmp, SID))).toBe(false);
  });

  it('is written when turns reach the cap, naming the session and the run', () => {
    process.env.ORK_GOAL_MAX_TURNS = '2';
    submit(`/goal ${CONDITION}`);
    stop(1);
    stop(2);

    expect(JSON.parse(readFileSync(brakePath(tmp, SID), 'utf8'))).toMatchObject({
      session_id: SID,
      prompt_id: RUN,
      reason: 'turns_cap',
      turns: 2,
      cap: 2,
    });
  });

  it('is written when tokens reach the cap', () => {
    process.env.ORK_GOAL_MAX_TOKENS = '10';
    submit(`/goal ${CONDITION}`);
    stop(1);
    expect(JSON.parse(readFileSync(brakePath(tmp, SID), 'utf8')).reason).toBe('tokens_cap');
  });

  it('still honors the older per-session variable name', () => {
    process.env.ORK_GOAL_MAX_TURNS_PER_SESSION = '1';
    submit(`/goal ${CONDITION}`);
    stop(1);
    expect(existsSync(brakePath(tmp, SID))).toBe(true);
  });

  it('stays deleted once the user deletes it: one trip per run', async () => {
    process.env.ORK_GOAL_MAX_TURNS = '1';
    submit(`/goal ${CONDITION}`);
    stop(1);
    rmSync(brakePath(tmp, SID));
    stop(2);

    expect(existsSync(brakePath(tmp, SID))).toBe(false);
    expect((await toolCall()).hookSpecificOutput?.permissionDecision).toBeUndefined();
  });

  it('is per session, so one run cannot release another', () => {
    process.env.ORK_GOAL_MAX_TURNS = '1';
    submit(`/goal ${CONDITION}`);
    submit(`/goal ${CONDITION}`, 'prompt-b', 'sess-b');
    stop(1);
    stop(1, 'prompt-b', 'sess-b');
    expect(existsSync(brakePath(tmp, SID))).toBe(true);
    expect(existsSync(brakePath(tmp, 'sess-b'))).toBe(true);
  });
});

describe('PreToolUse denies the tripped run', () => {
  beforeEach(() => {
    process.env.ORK_GOAL_MAX_TURNS = '1';
    submit(`/goal ${CONDITION}`);
    stop(1);
  });

  it.each(['Bash', 'Write', 'Read', 'Agent', 'Grep', 'mcp__server__tool'])('denies %s', async tool => {
    const result = await toolCall({ tool_name: tool, tool_input: { command: 'ls', file_path: '/tmp/x' } });
    expect(result.hookSpecificOutput?.permissionDecision).toBe('deny');
    // Deny alone did not end a live /goal run (CC 2.1.332): continue:false ends it.
    expect(result.continue).toBe(false);
  });

  it('gives a reason with the numbers and the override, never the goal condition', async () => {
    const reason = (await toolCall()).hookSpecificOutput?.permissionDecisionReason ?? '';
    expect(reason).toContain('1 turn');
    expect(reason).toContain('cap 1');
    expect(reason).toContain('/goal clear');
    expect(reason).toContain('.claude/state/goal-budget-tripped');
    expect(reason).not.toContain(CONDITION);
  });

  it('tells the user the same reason through stopReason', async () => {
    const result = await toolCall();
    expect(result.stopReason).toBe(result.hookSpecificOutput?.permissionDecisionReason);
    expect(result.hookSpecificOutput?.hookEventName).toBe('PreToolUse');
  });

  it('leaves an untripped call without continue:false', async () => {
    expect((await toolCall({ prompt_id: 'prompt-2' })).continue).toBe(true);
  });

  it.each([
    ['another session', { session_id: 'sess-other' }],
    ['a new prompt', { prompt_id: 'prompt-2' }],
    ['a call with no prompt_id', { prompt_id: undefined }],
  ])('lets through %s', async (_label, over) => {
    expect((await toolCall(over)).hookSpecificOutput?.permissionDecision).toBeUndefined();
  });
});

/**
 * A background task that finishes starts a turn through UserPromptSubmit with a
 * NEW prompt_id (48 of 48 in this repo's transcripts). It is not a user prompt.
 */
describe('a task notification carries the run', () => {
  const NOTICE = '<task-notification>\n<task-id>abc</task-id>\n</task-notification>';

  it('keeps the run open under the new prompt_id and goes on counting', () => {
    submit(`/goal ${CONDITION}`);
    stop(1);
    expect(submit(NOTICE, 'prompt-notice')).toEqual(SILENT);
    stop(2, 'prompt-notice');

    expect(openRun()?.start.prompt_id).toBe('prompt-notice');
    expect(openRun()?.tally?.turn_count).toBe(2);
  });

  it('moves a tripped brake to the new prompt_id', async () => {
    process.env.ORK_GOAL_MAX_TURNS = '1';
    submit(`/goal ${CONDITION}`);
    stop(1);
    submit(NOTICE, 'prompt-notice');

    expect((await toolCall({ prompt_id: 'prompt-notice' })).hookSpecificOutput?.permissionDecision).toBe('deny');
  });

  it('does not bring back a brake the user deleted', () => {
    process.env.ORK_GOAL_MAX_TURNS = '1';
    submit(`/goal ${CONDITION}`);
    stop(1);
    rmSync(brakePath(tmp, SID));
    submit(NOTICE, 'prompt-notice');

    expect(existsSync(brakePath(tmp, SID))).toBe(false);
  });

  it('opens no run when none is open', () => {
    submit(NOTICE, 'prompt-notice');
    expect(existsSync(join(tmp, '.claude', 'state', 'goal-history.jsonl'))).toBe(false);
  });

  it('treats a notification that quotes a /goal line as a notification', () => {
    submit(`/goal ${CONDITION}`);
    stop(1);
    submit('<task-notification>\n/goal something quoted in a result\n</task-notification>', 'prompt-notice');

    expect(openRun()?.start.condition).toBe(CONDITION);
    expect(openRun()?.tally?.turn_count).toBe(1);
  });
});

describe('edges', () => {
  it.each(['clear', 'stop', 'off', 'reset', 'none', 'cancel', 'CLEAR'])(
    '/goal %s closes the run and opens none',
    word => {
      submit(`/goal ${CONDITION}`);
      stop(1);
      submit(`/goal ${word}`, 'prompt-2');
      expect(openRun()).toBeNull();
    },
  );

  it('a bare /goal opens no run', () => {
    submit(`/goal ${CONDITION}`);
    submit('/goal', 'prompt-2');
    expect(openRun()).toBeNull();
  });

  it('a condition that only starts with an alias word is a real goal', () => {
    submit('/goal stop the flaky test');
    expect(openRun()?.start.condition).toBe('stop the flaky test');
  });

  it('keeps the brake file inside .claude/state for a hostile session_id', () => {
    const path = brakePath(tmp, '../../../etc/passwd');
    expect(path.startsWith(join(tmp, '.claude', 'state') + '/') || path.startsWith(join(tmp, '.claude', 'state') + '\\')).toBe(true);
    expect(path).not.toContain('..');
  });

  it('a late Stop from a closed run writes no tally and no brake', () => {
    process.env.ORK_GOAL_MAX_TURNS = '1';
    submit(`/goal ${CONDITION}`);
    submit('something else', 'prompt-2');
    stop(1);
    expect(existsSync(brakePath(tmp, SID))).toBe(false);
    expect(history().some(row => row.kind === 'tally')).toBe(false);
  });

  it('survives a corrupt brake file and a torn history line', async () => {
    submit(`/goal ${CONDITION}`);
    appendFileSync(join(tmp, '.claude', 'state', 'goal-history.jsonl'), '{"torn\n');
    stop(1);
    writeFileSync(brakePath(tmp, SID), 'not json');
    expect(openRun()?.tally?.turn_count).toBe(1);
    expect((await toolCall()).hookSpecificOutput?.permissionDecision).toBeUndefined();
  });
});

describe('closing a run', () => {
  it('the next prompt closes it with the tally and removes its brake', () => {
    process.env.ORK_GOAL_MAX_TURNS = '2';
    submit(`/goal ${CONDITION}`);
    stop(1);
    stop(2);
    expect(submit('never mind, do something else', 'prompt-2')).toEqual(SILENT);

    expect(history().at(-1)).toMatchObject({ prompt_id: RUN, turn_count: 2, status: 'braked' });
    expect(openRun()).toBeNull();
    expect(existsSync(brakePath(tmp, SID))).toBe(false);
  });

  it('a new /goal is never blocked, even right after a trip', () => {
    process.env.ORK_GOAL_MAX_TURNS = '1';
    submit(`/goal ${CONDITION}`);
    stop(1);
    expect(submit('/goal try again', 'prompt-2')).toEqual(SILENT);
    expect(openRun()?.start.prompt_id).toBe('prompt-2');
  });

  it('SessionEnd closes the open run with status from the tally', () => {
    submit(`/goal ${CONDITION}`);
    stop(1);
    stop(2);
    expect(goalBudgetGuard({ tool_name: '', session_id: SID, tool_input: {} }, ctx())).toEqual(SILENT);
    expect(history().at(-1)).toMatchObject({ turn_count: 2, status: 'ended' });
    expect(openRun()).toBeNull();
  });

  it('SessionEnd marks a run with no Stop as aborted', () => {
    submit(`/goal ${CONDITION}`);
    goalBudgetGuard({ tool_name: '', session_id: SID, tool_input: {} }, ctx());
    expect(history().at(-1)).toMatchObject({ turn_count: 0, status: 'aborted' });
  });
});
